import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('chunks_csv/moran_global_2021_no2.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Create a dictionary to store the NO2 values for each borough
no2_values = {}
for index, row in df.iterrows():
    no2_values[row['borough']] = row['NO2_value']

# Create a dictionary to store the neighbors for each borough
neighbors = {}
for index, row in adjacency_df.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = []
    neighbors[row['borough']].append(row['neighbor'])

# Create a list to store the Moran's I values
moran_i_values = []

# Iterate over each borough
for borough in no2_values:
    # Get the NO2 values for the current borough and its neighbors
    values = [no2_values[borough]]
    for neighbor in neighbors.get(borough, []):
        values.append(no2_values[neighbor])

    # Calculate the Moran's I value
    mean_value = np.mean(values)
    variance = np.var(values)
    if variance == 0:
        moran_i = 0
    else:
        cov = np.cov(values, rowvar=False)
        if len(cov) == 1:
            moran_i = 0
        else:
            moran_i = cov[0, 0] / (variance * mean_value)
    moran_i_values.append(moran_i)

# Calculate the mean and standard deviation of the Moran's I values
mean_moran_i = np.mean(moran_i_values)
std_moran_i = np.std(moran_i_values)

# Perform a permutation test to determine the significance of the result
p_value = 0
for _ in range(500):
    # Shuffle the NO2 values
    shuffled_no2_values = {k: v for k, v in no2_values.items()}
    for borough in shuffled_no2_values:
        neighbors_list = neighbors.get(borough, [])
        for neighbor in neighbors_list:
            shuffled_no2_values[neighbor], shuffled_no2_values[borough] = shuffled_no2_values[borough], shuffled_no2_values[neighbor]

    # Calculate the Moran's I value for the shuffled data
    shuffled_moran_i_values = []
    for borough in shuffled_no2_values:
        values = [shuffled_no2_values[borough]]
        for neighbor in neighbors.get(borough, []):
            values.append(shuffled_no2_values[neighbor])
        mean_value = np.mean(values)
        variance = np.var(values)
        if variance == 0:
            moran_i = 0
        else:
            cov = np.cov(values, rowvar=False)
            if len(cov) == 1:
                moran_i = 0
            else:
                moran_i = cov[0, 0] / (variance * mean_value)
        shuffled_moran_i_values.append(moran_i)

    # Update the p-value
    p_value += (mean_moran_i - np.mean(shuffled_moran_i_values)) > 0

# Print the results
print(f"Mean Moran's I: {mean_moran_i}")
print(f"Standard Deviation of Moran's I: {std_moran_i}")
print(f"P-value: {p_value / 500}")
if p_value / 500 < 0.05:
    print(f"FINAL ANSWER: CLUSTERED (statistical method = Moran's I, p = {p_value / 500})")
else:
    print(f"FINAL ANSWER: NOT CLUSTERED (statistical method = Moran's I, p = {p_value / 500})")
